CREATE TABLE institutional_match_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, institution_id uuid NOT NULL, match_score integer NOT NULL DEFAULT 0, match_state text NOT NULL DEFAULT 'matched', authorization_state text NOT NULL DEFAULT 'pending_authorization', authorized_by text, authorized_at timestamptz, submission_state text NOT NULL DEFAULT 'not_submitted', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,institution_id));